style.css:
@-moz-document domain("classroom.google.com") {
/* Fondo general */
  body, .YVvGBb {
    background-color: #c7e8a7 !important;
    background-image: url("https://images.unsplash.com/photo-1503264116251-35a269479413"); /* Cambia esta URL si quieres otra imagen */
    background-size: cover !important;
    background-attachment: fixed !important;
    color: black !important;
  }

  /* Tarjetas de clases */
  .zWGUib, .kix-appview-editor {
    background-color: rgba(255, 255, 255, 0.85) !important; /* Fondo claro con transparencia */
    color: black !important;
    border-radius: 12px !important;
  }

  /* Textos generales */
  .YVvGBb, .JIlhhe, .zWGUib, .j8U29b, .GvcuGe {
    color: black !important;
  }

  /* Encabezado */
  .Gmjzdc {
    background-color: rgba(255, 255, 255, 0.8) !important;
    color: black !important;
  }

  /* Quita algunas sombras molestas */
  * {
    box-shadow: none !important;
  }
}
